<?php require_once __DIR__.'/../includes/bootstrap.php';require_customer();$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM orders WHERE order_id=? AND customer_id=? LIMIT 1');$s->execute([$id,$_SESSION['customer_id']]);$o=$s->fetch();if(!$o){http_response_code(404);exit('Order not found.');}$s=$pdo->prepare('SELECT oi.*,p.product_name,p.image_url FROM order_items oi JOIN products p ON p.product_id=oi.product_id WHERE oi.order_id=?');$s->execute([$id]);$items=$s->fetchAll();$s=$pdo->prepare('SELECT * FROM order_status_history WHERE order_id=? ORDER BY created_at ASC,id ASC');$s->execute([$id]);$history=$s->fetchAll();$payment=null;if(strtoupper((string)($o['payment_method']??''))==='MPESA'){try{$ps=$pdo->prepare('SELECT * FROM mpesa_payments WHERE order_id=? ORDER BY id DESC LIMIT 1');$ps->execute([$id]);$payment=$ps->fetch()?:null;}catch(Throwable $ignore){$payment=null;}}$statuses=['PENDING','CONFIRMED','PROCESSING','PACKED','DISPATCHED','OUT_FOR_DELIVERY','DELIVERED'];$currentIndex=array_search($o['status'],$statuses,true);$progress=$o['status']==='CANCELLED'?0:(int)round((($currentIndex+1)/count($statuses))*100);$latest=$history?end($history):null;$title='Track '.$o['order_number'];require __DIR__.'/../includes/header.php';?><div class="section-head"><div><span class="eyebrow">ORDER TRACKING</span><h1><?=e($o['order_number'])?></h1><p>Live status: <span class="status-pill <?=e(order_status_class($o['status']))?>"><?=e(order_status_label($o['status']))?></span></p></div><a class="btn ghost" href="/customer/orders.php">← My orders</a></div><?php if($o['status']==='DELIVERED'): ?><div class="delivery-success"><div>🎉</div><div><h2>Congratulations! Your order has been delivered.</h2><p>Thank you for shopping with Shadril Shopping Store. We hope you enjoy your purchase.</p><a class="btn primary" href="/customer/reviews.php">Rate your products</a></div></div><?php elseif($o['status']==='CANCELLED'): ?><div class="errors"><strong>This order was cancelled.</strong><p>Please contact support if you need help.</p></div><?php endif; ?>
<?php if(strtoupper((string)($o['payment_method']??''))==='MPESA'): ?>
<section class="panel payment-status-panel"><span class="eyebrow">M-PESA PAYMENT</span><h2>Payment status: <?=e(strtoupper((string)($payment['status']??'NOT STARTED')))?></h2>
<?php if(!$payment): ?><p>No M-Pesa attempt is recorded for this order yet. Please contact store support before making another payment.</p>
<?php elseif(strtoupper((string)$payment['status'])==='SUCCESS'): ?><p>Your payment is recorded as successful.</p><?php if(!empty($payment['mpesa_receipt'])): ?><p><strong>M-Pesa receipt:</strong> <?=e($payment['mpesa_receipt'])?></p><?php endif; ?>
<?php elseif(strtoupper((string)$payment['status'])==='PENDING'): ?><p>The payment result has not been confirmed yet. Do not submit another payment. Refresh this page later or contact support if the status does not update.</p>
<?php elseif(in_array(strtoupper((string)$payment['status']),['FAILED','CANCELLED'],true)): ?><p><?=e((string)($payment['result_description']??'The previous payment attempt did not complete.'))?></p><form method="post" action="/customer/retry-mpesa.php"><?=csrf_field()?><input type="hidden" name="order_id" value="<?=$id?>"><button class="btn primary">Retry M-Pesa payment</button></form>
<?php else: ?><p>Please contact store support to verify the payment status before trying again.</p><?php endif; ?></section>
<?php elseif(strtoupper((string)($o['payment_method']??''))==='POCHI'): ?><section class="panel payment-status-panel"><span class="eyebrow">POCHI LA BIASHARA</span><h2>Manual payment instructions</h2><p><strong>Business name:</strong> <?=e((string)store_config_value('pochi_name','Pochi la Biashara'))?></p><p><strong>Phone:</strong> <?=e((string)store_config_value('pochi_number',''))?></p><p><?=nl2br(e((string)store_config_value('pochi_instructions','Follow the store payment instructions and contact support to confirm your payment.')))?></p><p>Payment is confirmed manually by store management; this page does not automatically verify Pochi payments.</p></section><?php else: ?><section class="panel payment-status-panel"><span class="eyebrow">PAYMENT METHOD</span><p>Cash on delivery</p></section><?php endif; ?>
<div class="tracking-layout"><section class="panel"><h2>Live delivery progress</h2><div class="tracking-progress"><div><strong><?=$progress?>%</strong><span>journey completed</span></div><div class="progress-bar"><i style="width:<?=$progress?>%"></i></div><?php if($latest): ?><div class="latest-update"><strong>Latest update: <?=e(order_status_label($latest['status']))?></strong><span><?=e($latest['notes']??'No additional note.')?> · <?=e($latest['created_at'])?></span></div><?php endif; ?><div class="tracking-steps"><?php foreach($statuses as $i=>$st): $done=array_search($st,$statuses)<=array_search($o['status'],$statuses); if($o['status']==='CANCELLED')$done=false; ?><div class="track-step <?= $done?'done':''?> <?= $st===$o['status']?'current':''?>"><span><?= $done?'✓':($i+1)?></span><div><strong><?=e(order_status_label($st))?></strong><?php $last=null;foreach($history as $h)if($h['status']===$st)$last=$h; ?><small><?= $last?e($last['created_at']):'Waiting for update' ?></small></div></div><?php endforeach; ?></div></section><aside class="summary"><h2>Order summary</h2><div class="tracking-help"><strong>What happens next?</strong><p>Management updates the order status as it moves through confirmation, packing, dispatch and delivery. Refresh this page to see the latest checkpoint.</p></div><?php if(!empty($o['tracking_location'])||!empty($o['tracking_eta'])):?><div class="tracking-current"><strong>Current delivery checkpoint</strong><?php if(!empty($o['tracking_location'])):?><span>📍 <?=e($o['tracking_location'])?></span><?php endif;?><?php if(!empty($o['tracking_eta'])):?><span>Estimated update/delivery: <?=e(date('d M Y, H:i',strtotime($o['tracking_eta'])))?></span><?php endif;?></div><?php endif;?><?php foreach($items as $it): ?><div><span><?=e($it['product_name'])?> × <?=e((string)$it['quantity'])?></span><strong><?=money((float)$it['unit_price']*(int)$it['quantity'])?></strong></div><?php endforeach; ?><hr><div><strong>Total</strong><strong><?=money((float)$o['total_amount'])?></strong></div><p><strong>Delivery:</strong><br><?=e($o['delivery_address'])?><br><?=e($o['phone'])?></p></aside></div><section class="panel tracking-history"><div class="section-head"><div><h2>Status history</h2><small class="muted">Automatically refreshes every 30 seconds while the order is active.</small></div></div><?php foreach($history as $h): ?><div><span class="status-pill <?=e(order_status_class($h['status']))?>"><?=e(order_status_label($h['status']))?></span><span><?=e($h['notes']??'')?></span><small><?=e($h['created_at'])?></small></div><?php endforeach; ?></section><script>setTimeout(function(){location.reload();},30000);</script><?php require __DIR__.'/../includes/footer.php'; ?>
